const frag = `
	#ifdef GL_ES
precision mediump float;
#endif


uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;


// Some useful functions
vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec3 permute(vec3 x) { return mod289(((x*34.0)+1.0)*x); }

//
// Description : GLSL 2D simplex noise function
//      Author : Ian McEwan, Ashima Arts
//  Maintainer : ijm
//     Lastmod : 20110822 (ijm)
//     License :
//  Copyright (C) 2011 Ashima Arts. All rights reserved.
//  Distributed under the MIT License. See LICENSE file.
//  https://github.com/ashima/webgl-noise
//
float snoise(vec2 v) {

    // Precompute values for skewed triangular grid
    const vec4 C = vec4(0.211324865405187,
                        // (3.0-sqrt(3.0))/6.0
                        0.366025403784439,
                        // 0.5*(sqrt(3.0)-1.0)
                        -0.577350269189626,
                        // -1.0 + 2.0 * C.x
                        0.024390243902439);
                        // 1.0 / 41.0

    // First corner (x0)
    vec2 i  = floor(v + dot(v, C.yy));
    vec2 x0 = v - i + dot(i, C.xx);

    // Other two corners (x1, x2)
    vec2 i1 = vec2(0.0);
    i1 = (x0.x > x0.y)? vec2(1.0, 0.0):vec2(0.0, 1.0);
    vec2 x1 = x0.xy + C.xx - i1;
    vec2 x2 = x0.xy + C.zz;

    // Do some permutations to avoid
    // truncation effects in permutation
    i = mod289(i);
    vec3 p = permute(
            permute( i.y + vec3(0.0, i1.y, 1.0))
                + i.x + vec3(0.0, i1.x, 1.0 ));

    vec3 m = max(0.5 - vec3(
                        dot(x0,x0),
                        dot(x1,x1),
                        dot(x2,x2)
                        ), 0.0);

    m = m*m ;
    m = m*m ;

    // Gradients:
    //  41 pts uniformly over a line, mapped onto a diamond
    //  The ring size 17*17 = 289 is close to a multiple
    //      of 41 (41*7 = 287)

    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;

    // Normalise gradients implicitly by scaling m
    // Approximation of: m *= inversesqrt(a0*a0 + h*h);
    m *= 1.79284291400159 - 0.85373472095314 * (a0*a0+h*h);

    // Compute final noise value at P
    vec3 g = vec3(0.0);
    g.x  = a0.x  * x0.x  + h.x  * x0.y;
    g.yz = a0.yz * vec2(x1.x,x2.x) + h.yz * vec2(x1.y,x2.y);
    return 130.0 * dot(m, g);
}

float nsdCircle( vec2 p, float r )
{
    return length(p) - r+ snoise(vec2(p.x*(p.y*0.5), (p.y+u_time/3.))*2.)/20.;
}

void main() {
   vec2 st = gl_FragCoord.xy/u_resolution.xy;
   st.x *= u_resolution.x/u_resolution.y;
	 vec3 bgcolor= vec3(0.2156, 0.2470, 0.3176);

	 vec3 puceBlob= vec3(smoothstep(0.2, 0.202, nsdCircle(st-vec2(0.5, 0.5), 0.2)));
	 vec3 puceBlobC1= vec3(0.8078, 0.4823, 0.5686);
	 vec3 puceBlobC2= vec3(.0);
	 vec3 pbGrad= vec3(smoothstep(0.00, 0.222, nsdCircle(st-vec2(0.5, 0.5), 0.2)));
	 vec3 pbcf= mix(puceBlobC1, puceBlobC2, pbGrad);
	 vec3 ii=mix(pbcf, bgcolor, puceBlob);

	 vec3 happyBlob= vec3(smoothstep(0.15, 0.152, nsdCircle(st-vec2(0.5, 0.5), .15)));
	 vec3 happyBlobC1= vec3(1.0, 0.7686, 0.5098);
	 vec3 happyBlobC2= vec3(0.);
	 vec3 hbGrad= vec3(smoothstep(0.00, 0.152, nsdCircle(st-vec2(0.5, 0.5), .15)));
	 vec3 hbcf= mix(happyBlobC1, happyBlobC2, hbGrad);
	 vec3 i= mix(hbcf, ii,happyBlob);

   vec3 sadBlob= vec3(smoothstep(0.1, 0.102, nsdCircle(st-vec2(0.5, 0.5), .1)));
	 vec3 sadblobC1= vec3(0.4, 0.6, 0.6078);
	 vec3 sadblobC2= vec3(.0);
	 vec3 sbGrad= vec3(smoothstep(0.00, 0.122, nsdCircle(st-vec2(0.5, 0.5), .1)));
	 vec3 sbcf= mix(sadblobC1, sadblobC2, sbGrad);


	 vec3 f= mix(sbcf, i, sadBlob);
	 gl_FragColor = vec4(vec3(f), 1.0);
}
`

